CREATE TABLE flags (key TEXT PRIMARY KEY,enabled BOOLEAN NOT NULL DEFAULT false,killed BOOLEAN NOT NULL DEFAULT false,version INTEGER NOT NULL DEFAULT 1,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE overrides (flag_key TEXT REFERENCES flags(key) ON DELETE CASCADE,tenant_id UUID NOT NULL,enabled BOOLEAN NOT NULL,PRIMARY KEY(flag_key,tenant_id));
CREATE TABLE audit (id BIGSERIAL PRIMARY KEY,actor_id UUID NOT NULL,tenant_id UUID NOT NULL,action TEXT NOT NULL,flag_key TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
